package com.vandorlabs.physics;
import java.util.*;
public final class CouplerBodyPriorTest {
 private static int checks;private static volatile double sink;
 private static void need(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}
 private static void matrix(double[] a,double[] b,double eps,String s){for(int i=0;i<9;i++)need(Math.abs(a[i]-b[i])<=eps,s+" entry="+i);}
 private static double[] vector(double[] r,double x,double y,double z){return new double[]{r[0]*x+r[1]*y+r[2]*z,r[3]*x+r[4]*y+r[5]*z,r[6]*x+r[7]*y+r[8]*z};}
 private static void proper(double[] r){for(int a=0;a<3;a++)for(int b=0;b<3;b++)need(Math.abs(r[a]*r[b]+r[3+a]*r[3+b]+r[6+a]*r[6+b]-(a==b?1:0))<2e-7,"proper orthonormal result");double det=r[0]*(r[4]*r[8]-r[5]*r[7])-r[1]*(r[3]*r[8]-r[5]*r[6])+r[2]*(r[3]*r[7]-r[4]*r[6]);need(Math.abs(det-1)<2e-7,"proper determinant");}
 private static void directions(){double[] id=RigidTransform.IDENTITY.r,out=new double[9];need(CouplerBodyPrior.write(id,2,0,0,0,0,0,2,-.04,0,Math.toRadians(4),out)==CouplerBodyPrior.Status.APPLIED,"gravity on X-offset centre produces Z rotation");matrix(out,RigidTransform.rotation(0,0,1,Math.toDegrees(Math.atan2(-.04,2))).r,1e-12,"natural Z roll");need(out[3]<0&&out[6]==0,"not a fabricated yaw or pitch lock");
  Random random=new Random(42351);for(int i=0;i<2000;i++){double x=random.nextDouble()*2-1,y=random.nextDouble()*2-1,z=random.nextDouble()*2-1,u=random.nextDouble()*2-1,v=random.nextDouble()*2-1,w=random.nextDouble()*2-1;double len=Math.hypot(Math.hypot(x,y),z),desired=Math.hypot(Math.hypot(u,v),w);double[] prior=RigidTransform.rotation(x,y,z,random.nextDouble()*360-180).r,saved=prior.clone();double[] current=vector(prior,x,y,z);double px=1e6,py=-2e6,pz=3e6;CouplerBodyPrior.Status status=CouplerBodyPrior.write(prior,current[0]+px,current[1]+py,current[2]+pz,px,py,pz,u+px,v+py,w+pz,Math.PI,out);need(status==CouplerBodyPrior.Status.APPLIED||status==CouplerBodyPrior.Status.UNCHANGED,"finite full directional correction");double[] aligned=vector(out,x,y,z);need(Math.abs(aligned[0]/len-u/desired)<2e-8&&Math.abs(aligned[1]/len-v/desired)<2e-8&&Math.abs(aligned[2]/len-w/desired)<2e-8,"shortest correction aligns centre direction");proper(out);matrix(saved,prior,0,"input unchanged");double[] alias=prior.clone();CouplerBodyPrior.write(alias,current[0]+px,current[1]+py,current[2]+pz,px,py,pz,u+px,v+py,w+pz,Math.PI,alias);matrix(out,alias,0,"output alias uses original nine entries");}}
 private static void bounds(){double[] id=RigidTransform.IDENTITY.r,out=new double[9];for(double step:new double[]{0,1e-7,Math.toRadians(4),.5,Math.PI}){CouplerBodyPrior.write(id,1,0,0,0,0,0,-1,0,0,step,out);proper(out);matrix(out,RigidTransform.rotation(0,0,-1,Math.toDegrees(step)).r,1e-12,"deterministic antiparallel least-basis cross lever");double angle=new RigidTransform(out,0,0,0).angle();need(angle<=Math.toDegrees(step)+1e-6,"bounded antiparallel correction");}double[] prior=RigidTransform.rotation(1,0,0,63).r;CouplerBodyPrior.write(prior,2,0,0,0,0,0,0,2,0,Math.PI,out);matrix(out,RigidTransform.rotation(0,0,1,90).then(new RigidTransform(prior,0,0,0)).r,1e-12,"left composition retains unconstrained prior twist");
  for(double tiny:new double[]{0,1e-12,1e-9}){need(CouplerBodyPrior.write(prior,tiny,0,0,0,0,0,1,2,3,.1,out)==CouplerBodyPrior.Status.DEGENERATE,"tiny current lever explicit");matrix(out,prior,0,"degenerate current copies prior");need(CouplerBodyPrior.write(prior,1,2,3,0,0,0,tiny,0,0,.1,out)==CouplerBodyPrior.Status.DEGENERATE,"tiny desired lever explicit");matrix(out,prior,0,"degenerate desired copies prior");}need(CouplerBodyPrior.write(prior,1,2,3,0,0,0,1,2,3,.1,out)==CouplerBodyPrior.Status.UNCHANGED,"same direction unchanged");matrix(out,prior,0,"unchanged copy exact");
  for(double invalid:new double[]{-1,Math.PI+.1,Double.NaN,Double.POSITIVE_INFINITY}){Arrays.fill(out,17);need(CouplerBodyPrior.write(id,1,0,0,0,0,0,0,1,0,invalid,out)==CouplerBodyPrior.Status.INVALID,"step bounds");for(double x:out)need(x==17,"invalid leaves output untouched");}double[] bad=id.clone();bad[0]=-1;Arrays.fill(out,21);need(CouplerBodyPrior.write(bad,1,0,0,0,0,0,0,1,0,.1,out)==CouplerBodyPrior.Status.INVALID,"reflected prior invalid");for(double x:out)need(x==21,"invalid matrix leaves output untouched");need(CouplerBodyPrior.write(id,Double.MAX_VALUE,0,0,-Double.MAX_VALUE,0,0,0,1,0,.1,out)==CouplerBodyPrior.Status.INVALID,"overflow lever invalid");double[] args={1,0,0,0,0,0,0,1,0,.1};for(int i=0;i<args.length;i++){double saved=args[i];for(double invalid:new double[]{Double.NaN,Double.POSITIVE_INFINITY,Double.NEGATIVE_INFINITY}){args[i]=invalid;Arrays.fill(out,31);need(CouplerBodyPrior.write(id,args[0],args[1],args[2],args[3],args[4],args[5],args[6],args[7],args[8],args[9],out)==CouplerBodyPrior.Status.INVALID,"each nonfinite scalar refused");for(double value:out)need(value==31,"all invalid scalar outputs unchanged");}args[i]=saved;}}
 private static void inertia(){double[] prior=RigidTransform.rotation(1,0,0,25).r,out=new double[9];double oldCentreX=4,oldCentreY=3,oldCentreZ=2,newPivotX=.2,newPivotY=.1,newPivotZ=0;double[] oldLever={oldCentreX,oldCentreY,oldCentreZ},neutral=vector(prior,oldLever[0],oldLever[1],oldLever[2]);double targetY=oldCentreY-.04;CouplerBodyPrior.write(prior,newPivotX+neutral[0],newPivotY+neutral[1],newPivotZ+neutral[2],newPivotX,newPivotY,newPivotZ,oldCentreX,targetY,oldCentreZ,Math.toRadians(4),out);proper(out);need(new RigidTransform(out,0,0,0).r[5]!=prior[5],"actual inertial centre and moved pivot produce correction");}
 @SuppressWarnings("deprecation") // Thread.getId retains the Java 8 contract for both JDKs.
 private static void cost(){double[] prior=RigidTransform.rotation(1,0,0,25).r,out=new double[9];com.sun.management.ThreadMXBean bean=(com.sun.management.ThreadMXBean)java.lang.management.ManagementFactory.getThreadMXBean();bean.setThreadAllocatedMemoryEnabled(true);long id=Thread.currentThread().getId();for(int i=0;i<20000;i++)CouplerBodyPrior.write(prior,2,0,0,0,0,0,2,-.04,0,.07,out);long bytes=bean.getThreadAllocatedBytes(id),start=System.nanoTime();for(int i=0;i<10000;i++){need(CouplerBodyPrior.write(prior,2,0,0,0,0,0,2,-.04,0,.07,out)==CouplerBodyPrior.Status.APPLIED,"warm scalar call");sink=out[0];}long allocated=bean.getThreadAllocatedBytes(id)-bytes;need(allocated==0,"zero warmed helper allocation: "+allocated);System.out.println("Body prior warm calls10000 bytes="+allocated+" nanos="+(System.nanoTime()-start));}
 public static void main(String[] args){directions();bounds();inertia();cost();System.out.println("Coupler body prior PASS checks="+checks+" shortestSO3/worldinertia/Zroll/twist/alias/degenerate/antiparallel/invalid/bounds");}
}
